new={
'Quad3h':{'p':'100-102','or':'Concéde, quǽsumus omnípotens Deus: ut jejuniórum nobis sancta devótio, et purificatiónem tríbuat; et majestáti tuæ nos reddat accéptos: Per Dóminum.',
 'se':'Efficiátur hæc hóstia, quǽsumus Dómine, solémnibus grata jejúniis: et ut tibi fiat accéptior, purificátis méntibus immolétur. Per Dóminum.',
 'pc':'Sacraménti tui, Dómine, veneránda percéptio: et mýstico nos mundet efféctu; et perpétua virtúte deféndat: Per Dóminum.'},
'Pasc6s':{'p':'243-244','or':'Præsta, quǽsumus omnípotens Deus: ut claritátis tuæ super nos splendor effúlgeat; et lux tuæ lucis corda eórum, qui per grátiam tuam renáti sunt, Sancti Spíritus illustratióne confírmet: Per Dóminum ejúsdem.',
 'se':'Múnera, quǽsumus, Dómine, obláta sanctífica, et corda nostra Sancti Spíritus illustratióne emúnda. Per Dóminum ejúsdem.',
 'pc':'Sancti Spíritus, Dómine, corda nostra mundet infúsio; et sui roris íntima aspersióne fecúndet. Per Dóminum ejúsdem.'},
'S0113':{'p':'38-39 (In Octava Epiphaniae)','or':'Deus, cujus Unigénitus in substántia nostræ carnis appáruit: præsta quǽsumus, ut per eum, quem símilem nobis foris agnóvimus; intus reformári mereámur: Qui tecum.',
 'se':'Hóstias tibi, Dómine, pro nati Fílii tui apparitióne deférimus, supplíciter exorántes: ut sicut ipse nostrórum auctor est múnerum, ita sit ipse miséricors et suscéptor: Jesus Christus Dóminus noster, qui tecum.',
 'pc':'Cælésti lúmine, quǽsumus Dómine, semper et ubíque nos prǽveni: ut mystérium, cujus nos partícipes esse voluísti; et puro cernámus intúitu, et digno percipiámus afféctu: Per Dóminum.'},
'S0814':{'p':'527-528','or':'Deus, qui virginálem aulam beátæ Maríæ, in qua habitáres, elígere dignátus es: da quǽsumus, ut sua nos defensióne munítos; jucúndos fácias suæ interésse festivitáti: Qui vivis et regnas.',
 'se':'Múnera nostra, Dómine, apud cleméntiam tuam Dei Genitrícis comméndet orátio: quam idcírco de præsénti sǽculo transtulísti, ut pro peccátis nostris apud te fiduciáliter intercédat. Per eúmdem Dóminum.',
 'pc':'Concéde, miséricors Deus, fragilitáti nostræ præsídium: ut qui sanctæ Dei Genitrícis festivitátem prævenímus; intercessiónis ejus auxílio, a nostris iniquitátibus resurgámus: Per eúmdem Dóminum.'},
'C64s':{'p':'42*-44*','or':'Deus, qui ad majestátis tuæ glóriam et géneris humáni salútem, Unigénitum tuum summum atque ætérnum constituísti Sacerdótem: præsta, ut quos minístros et mysteriórum suórum dispensatóres elégit; in accépto ministério adimpléndo fidéles inveniántur: Per eúmdem Dóminum.',
 'se':'Hæc múnera, Dómine, mediátor noster Jesus Christus tibi reddat accépta; et nos, una secum, hóstias tibi gratas exhíbeat: Qui tecum.',
 'pc':'Vivíficet nos, quǽsumus Dómine, divína quam obtúlimus et súmpsimus hóstia; ut perpétua tibi caritáte conjúncti, fructum, qui semper máneat, afferámus: Per Dóminum.'},
'C68s':{'p':'48*-50* (De Pœnis seu Passione D.N.J.C.)','or':'Omnípotens sempitérne Deus, qui passiónem Fílii tui Dómini nostri Jesu Christi in prétium redemptiónis humánæ misericórditer suscepísti: concéde propítius, ut sicut hódie pœnárum et dolórum passiónis ejus memóriam celebrámus; ita eorúmdem fructus mereámur esse partícipes: Per eúmdem Dóminum.',
 'se':'Omnípotens sempitérne Deus, qui Christi Fílii tui beáta passióne nos réparas, consérva in nobis ópera misericórdiæ tuæ: ut in hujus celebritáte mystérii, perpétua devotióne vivámus. Per eúmdem.',
 'pc':'Refécti vitálibus aliméntis, omnípotens Deus, te supplíciter exorámus; ut sicut pœnas et dolóres, quos Fílius tuus Dóminus noster in sua passióne sustínuit, devóto celebrámus afféctu: ita benígno semper nos prótegas auxílio; et contínua pietáte ab omni malo præsérves: Per eúmdem Dóminum.'},
'C85s':{'p':'66*-68* (Ad tollendum schisma)','or':'Deus, qui erráta córrigis, et dispérsa cóngregas, et congregáta consérvas: quǽsumus, super pópulum christiánum tuæ uniónis grátiam cleménter infúnde; ut divisióne rejécta, vero Pastóri Ecclésiæ tuæ se úniens, tibi digne váleat famulári: Per Dóminum.',
 'se':'Múnera hæc pro unióne pópuli christiáni tibi, Dómine, obláta sanctífica: per quæ unitátis et pacis in Ecclésia tua nobis dona concédas. Per Dóminum.',
 'pc':'Hæc tua, Dómine, sumpta sacra commúnio: sicut fidélium in te uniónem præsígnat; sic in tua Ecclésia unitátis, quǽsumus, operétur efféctum: Per Dóminum.'},
'C89s':{'p':'68*-70* (Pro eligendo summo Pontifice)','or':'Súpplici, Dómine, humilitáte depóscimus; ut sacrosánctæ Románæ Ecclésiæ concédat Pontíficem illum tua imménsa píetas: qui et pio in nos stúdio semper tibi plácitus; et tuo pópulo pro salúbri régimine sit assídue ad glóriam tui nóminis reveréndus: Per Dóminum.',
 'se':'Tuæ nobis, Dómine, abundántia pietátis indúlgeat, ut per sacra múnera, quæ tibi reverénter offérimus, gratum majestáti tuæ Pontíficem sanctæ matris Ecclésiæ régimini præésse gaudeámus. Per Dóminum.',
 'pc':'Pretiósi córporis et sánguinis tui nos, Dómine, sacraménto reféctos, mirífica tuæ majestátis grátia de illíus summi Pontíficis concessióne lætíficet: qui et plebem tuam virtútibus ínstruat; et fidélium mentes spirituálium arómatum odóre perfúndat: Qui vivis.'},
'C104s':{'p':'90*-91* (Pro vitanda mortalitate)','or':'Deus, qui non mortem, sed pœniténtiam desíderas peccatórum; pópulum tuum, quǽsumus, ad te convérte propítius: ut dum tibi devótus exsístit; iracúndiæ tuæ ab eo flagélla amóveas: Per Dóminum.',
 'se':'Subvéniat nobis, quǽsumus Dómine, sacrifícii præséntis oblátio: quæ nos et ab erróribus univérsis poténter absólvat, et a totíus erípiat perditiónis incúrsu. Per Dóminum.',
 'pc':'Exáudi nos Deus salutáris noster: et intercedénte beáta María semper vírgine cum ómnibus Sanctis; pópulum tuum ab iracúndiæ tuæ terróribus líberum, et misericórdiæ tuæ fac benignitáte secúrum: Per Dóminum.'},
'C110s':{'p':'94*-96*','or':'Deus, qui tam excellénti mystério conjugálem cópulam consecrásti, ut Christi et Ecclésiæ sacraméntum præsignáres in fœdere nuptiárum: præsta quǽsumus, ut quod nostro ministrátur offício; tua benedictióne pótius impleátur: Per Dóminum.',
 'se':'Súscipe, quǽsumus, Dómine, pro sacra connúbii lege munus oblátum: et cujus largítor es múneris, óperis esto dispósitor. Per Dóminum.',
 'pc':'Quǽsumus omnípotens Deus, institúta providéntiæ tuæ pio favóre comitáre: et quos legítima societáte connéctis; longǽva pietáte custódi: Per Dóminum.'},
'C114s':{'p':'114*-116* (In die obitus seu depositionis defuncti)','or':'Deus, cui próprium est miseréri semper, et párcere, te súpplices exorámus pro ánima fámuli tui N. quam hódie de hoc sǽculo migráre jussísti: ut non tradas eam in manus inimíci, neque obliviscáris in finem; sed júbeas eam a sanctis Angelis súscipi, et ad pátriam paradísi perdúci: ut quia in te sperávit, et crédidit, non pœnas ætérnas sustíneat; sed gáudia sempitérna possídeat: Per Dóminum.',
 'se':'Propitiáre, quǽsumus Dómine, ánimæ fámuli tui N. pro qua hóstiam laudis tibi immolámus, majestátem tuam supplíciter deprecántes: ut per hæc piæ placatiónis offícia, perveníre mereátur ad réquiem sempitérnam. Per Dóminum.',
 'pc':'Præsta, quǽsumus omnípotens Deus: ut ánima fámuli tui N. quæ hódie de hoc sǽculo migrávit; his sacrifíciis purgáta, et a peccátis expedíta, indulgéntiam páriter, et réquiem cápiat sempitérnam: Per Dóminum.'},
'S1113':{'p':'116*-118* (In anniversario defunctorum, pro pluribus)','or':'Deus indulgentiárum Dómine, da animábus famulórum, famularúmque tuárum, quorum anniversárium depositiónis diem commemorámus; refrigérii sedem, quiétis beatitúdinem, et lúminis claritátem: Per Dóminum.',
 'se':'Propitiáre Dómine supplicatiónibus nostris pro animábus famulórum, famularúmque tuárum, quorum hódie ánnua dies ágitur, pro quibus tibi offérimus sacrifícium laudis ut eas Sanctórum tuórum consórtio sociáre dignéris. Per Dóminum.',
 'pc':'Præsta, quǽsumus Dómine, ut ánimæ famulórum famularúmque tuárum, quorum anniversárium depositiónis diem commemorámus; his purgátæ sacrifíciis, indulgéntiam páriter, et réquiem cápiant sempitérnam: Per Dóminum.'},
'G420':{'p':'379-380 (In Apparitione B.M.V. Immaculatae, 11 Februarii)','or':'Deus, qui per Immaculátam Vírginis Conceptiónem dignum Fílio tuo habitáculum præparásti: súpplices a te quǽsumus, ut ejúsdem Vírginis Apparitiónem celebrántes; salútem mentis et córporis consequámur: Per eúmdem Dóminum.',
 'se':'Hóstia laudis, quam tibi, Dómine, per mérita gloriósæ et Immaculátæ Vírginis, offérimus, sit tibi in odórem suavitátis, et nobis optátam cónferat córporis et ánimæ sanitátem. Per Dóminum.',
 'pc':'Quos cælésti, Dómine, aliménto satiásti, súblevet déxtera Genitrícis tuæ Immaculátæ: ut ad ætérnam pátriam, ipsa adjuvánte, perveníre mereámur: Qui vivis.'},
'G505':{'p':'481-482 (In Commemoratione S. Pauli, 30 Junii)','or':'Deus, qui multitúdinem Géntium beáti Pauli Apóstoli prædicatióne docuísti: da nobis, quǽsumus, ut cujus natalítia cólimus; ejus apud te patrocínia sentiámus: Per Dóminum.',
 'se':'Hóstias, Dómine, quas nómini tuo sacrándas offérimus, Apostólica prosequátur orátio, per quam nos expiári tríbuas, et deféndi. Per Dóminum.',
 'pc':'Percéptis, Dómine, sacraméntis, beáto Paulo Apóstolo tuo interveniénte, deprecámur: ut quæ pro illíus celebráta sunt glória; nobis profíciant ad medélam: Per Dóminum.'},
}
